            if len(set(vals))>1: mc=('row',i,list(vals)); break
    kind,pos,seq=mc; K=len(seq)
    out=[r[:] for r in inp]
    if kind=='row':
        i=pos
        # neighbor line(s) adjacent kept: scan upward/downward for constant lines
        n=i-1
