            out[n]=inp[n][:]; n-=1
        n=i+1
        while 0<=n<h and len({inp[n][j] for j in range(w)})==1:
            out[n]=inp[n][:]; n+=1
        # body: all lines except seq line and kept neighbors; phase: seq[0] at first body line IF seq at top edge else seq[K-1] at nearest body line
        # determine edge: seq line at min index -> forward; at max index -> backward
        fwd = (pos == 0)  # seq at top edge => forward; at bottom edge => backward
        # build order of body lines in reading order, excluding seq line and kept
        kept=set(range(h))
