        if fwd:
            idx=0
            for r in body: out[r]=[seq[idx%K] for _ in range(w)]; idx+=1
        else:
            # nearest body line (adjacent to seq side) gets seq[K-1], next gets seq[K-2], ...
            # reading order: body lines sorted; nearest to seq is body[-1] if seq at bottom
            nb=body[-1] if pos==h-1 else body[0]
            idx=K-1
            for r in body:
                out[r]=[seq[idx%K] for _ in range(w)]; idx-=1
    else:
        j=pos
        n=j-1
        while 0<=n<w and len({inp[r][n] for r in range(h)})==1:
            for rr in range(h): out[rr][n]=inp[rr][n]; n-=1
        n=j+1
        while 0<=n<w and len({inp[r][n] for r in range(h)})==1:
            for rr in range(h): out[rr][n]=inp[rr][n]; n+=1
        kept=set(range(w))
        for c in range(w):
            if c!=j and c not in kept: kept.add(c)
        body=[c for c in range(w) if c!=j and c not in kept]
        fwd = (pos == w-1)  # seq at right edge -> backward (like seq at bottom)
        if fwd:
            idx=0
            for c in body:
                for r in range(h): out[r][c]=seq[idx%K]; idx+=1
        else:
            nb=body[0] if pos==w-1 else body[-1]
            idx=K-1
            for c in body:
                for r in range(h): out[r][c]=seq[idx%K]; idx-=1
    return out

